const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(key,label,primary=false,needs='')=>`<button type="button" data-ld="${esc(key)}"${needs?` data-ld-needs="${esc(needs)}"`:''} class="ld-button${primary?' ld-primary':''}">${esc(label)}</button>`;
const field=(key,label,value='',help='',decimal=false)=>`<div class="ld-field"><label for="ld-${key}">${esc(label)}</label><input id="ld-${key}" data-ld-field="${key}" name="${key}" value="${esc(value)}" type="text" ${decimal?'inputmode="decimal"':''} autocomplete="off" spellcheck="false">${help?`<small>${esc(help)}</small>`:''}</div>`;
const facts=entries=>`<dl class="ld-facts">${Object.entries(entries).map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`;
const decimal=value=>{try{const n=BigInt(value??0),whole=n/10n**18n,fraction=(n%10n**18n).toString().padStart(18,'0').replace(/0+$/,'');return whole+(fraction?'.'+fraction:'');}catch{return 'Unavailable';}};
const date=value=>{const d=new Date(Number(value)*1000);return Number.isFinite(d.getTime())?d.toISOString().replace('T',' ').slice(0,16)+' UTC':'Unavailable';};
const positive=value=>{try{return BigInt(value??0)>0n;}catch{return false;}};
const units=(value,symbol)=>`${value} ${symbol}`;
const validAddress=value=>/^0x[0-9a-f]{40}$/i.test(String(value||''))&&!/^0x0{40}$/i.test(value);

function lockHTML(lock,kind,s,native){
  const title=kind==='founder'?'Founder tokens':'Treasury funds',asset=kind==='founder'?s.symbol:native;
  if(!lock)return `<section class="ld-panel"><h4>${title}</h4><p>${s.phase==='refundable'?'No lock was created because the minimum raise was missed.':s.phase==='settled'?'This sale has no '+(kind==='founder'?'founder allocation.':'treasury allocation outside liquidity.'):'The lock is created only if the raise settles successfully.'}</p></section>`;
  const f=lock.formatted||{},ready=positive(lock.releasable),remaining=BigInt(lock.amount)-BigInt(lock.released),complete=remaining===0n;
  return `<section class="ld-panel"><div class="ld-panel-heading"><h4>${title}</h4><span class="ld-badge">${complete?'Fully released':ready?'Available to release':lock.linear?'Vesting':'Locked'}</span></div>${facts({'Committed amount':units(f.amount??decimal(lock.amount),asset),'Already released':units(f.released??decimal(lock.released),asset),'Available now':units(f.releasable??decimal(lock.releasable),asset),'Starts':date(lock.start),'First release':date(lock.cliff),'Fully vested':date(lock.end),'Schedule':lock.linear?'Linear vesting with a cliff':'One release at maturity','Fixed beneficiary':lock.beneficiary})}${ready?button('sale-release:'+kind,kind==='founder'?'Release vested founder tokens':'Release matured treasury',true):''}<p class="ld-note">The committed beneficiary receives the funds. Anyone can trigger an available release.</p></section>`;
}

/** Expects the verified CommunitySaleClient.read() shape. Actions absent from the state never render. */
export function renderSaleDetail(s,{amount='',native='ETH'}={}){
  const f=s.formatted||{},a=s.actions||{},number=(key)=>f[key]??decimal(s[key]),raised=BigInt(s.raised||0),hard=BigInt(s.hardCap||1),progress=Number(raised*10000n/(hard||1n)),status={scheduled:'Opens soon',funding:'Funding is open','awaiting-settlement':'Ready to settle',settled:'Raise complete',refundable:'Refunds available'}[s.phase]||'Sale state';
  const explanation={scheduled:'Contributions begin at the committed opening time.',funding:a.contribute?'Your final allocation depends on your share of the total raise. You may withdraw your contribution before close.':'The hard cap has been reached. Existing participants may withdraw before close; settlement still waits for the deadline.','awaiting-settlement':raised>=BigInt(s.softCap||0)?'The minimum raise was met. Settlement creates the market, commits seed liquidity and creates the chosen vesting locks.':'The minimum raise was missed. Settle once to make every recorded contribution fully refundable.',settled:'Purchased tokens are ready to claim. Seed liquidity remains permanently in the ANIMA market.',refundable:'The sale did not reach its minimum. Each contributor can claim their full recorded contribution.'}[s.phase]||'';
  const inputs=a.contribute||a.withdraw?field('saleAmount',`Amount · ${native}`,amount,a.withdraw?'Use this amount to contribute or withdraw from your existing contribution.':'This amount is contributed from the connected wallet.',true):'';
  return `<section class="ld-panel ld-sale-detail" aria-label="Community sale ${esc(s.id)}"><div class="ld-panel-heading"><div><span class="ld-eyebrow">COMMUNITY SALE / ${esc(s.id)}</span><h3>${esc(s.name)} <small>${esc(s.symbol)}</small></h3></div><span class="ld-badge">${status}</span></div><p>${esc(s.about||'')}</p><p>${esc(explanation)}</p><div class="ld-metrics">${facts({'Raised':units(number('raised'),native),'Minimum raise':units(number('softCap'),native),'Hard cap':units(number('hardCap'),native),'Your contribution':units(number('contribution'),native)})}</div><label for="ld-sale-progress-${esc(s.id)}">${Math.min(100,progress/100).toFixed(2)}% of the hard cap</label><progress id="ld-sale-progress-${esc(s.id)}" value="${Math.min(10000,progress)}" max="10000">${Math.min(100,progress/100).toFixed(2)}%</progress>${facts({'Opens':date(s.opens),'Closes':date(s.closes),'Token supply':units(number('supply'),s.symbol),'Community allocation':units(number('publicTokens'),s.symbol),'Liquidity allocation':units(number('lpTokens'),s.symbol),'Founder allocation':units(number('founderTokens'),s.symbol),'Raise used for liquidity':Number(s.liquidityBps)/100+'%','Vesting duration':s.vestingDays+' days'})}
    <section aria-label="Your participation"><h4>${a.claim?(s.phase==='refundable'?'Your refund':'Your token allocation'):'Your participation'}</h4>${a.claim?`<p><strong>${esc(units(number('claimable'),s.phase==='refundable'?native:s.symbol))}</strong> available to claim to ${esc(s.account)}.</p>`:s.claimed?'<p>Your allocation or refund has already been claimed.</p>':(s.phase==='settled'||s.phase==='refundable')?'<p>This wallet has no unclaimed allocation.</p>':''}${inputs}<div class="ld-actions">${a.contribute?button('sale-contribute','Review contribution',true):''}${a.withdraw?button('sale-withdraw','Review contribution withdrawal'):''}${a.settle?button('sale-settle',raised>=BigInt(s.softCap||0)?'Settle & create the market':'Settle & enable refunds',true):''}${a.claim?button('sale-claim',s.phase==='refundable'?'Claim full refund':'Claim purchased tokens',true):''}${button('read-sale','Refresh from chain')}</div></section>
    <p class="ld-note">This community raise seeds the built-in ANIMA market with permanent liquidity. Contributions, token balances and the launch room are public.</p><div class="ld-two">${lockHTML(s.founderLock,'founder',s,native)}${lockHTML(s.treasuryLock,'treasury',s,native)}</div><details><summary>Contracts and community</summary>${facts({'Token':s.token,'Creator':s.creator,'Launchpad':s.launchpad,'Market':s.market,'Vesting vault':s.vault,'Community room':s.room,'Read at block':s.blockNumber})}</details></section>`;
}

/** Real infrastructure steps; entered addresses are not described as verified until the load action succeeds. */
export function renderSaleSetup({config={},values={},account}={}){
  const v=Object.fromEntries(['saleCollection','saleLedger','saleMarket','saleVault','saleLaunchpad'].map(k=>[k,values[k]??config[k]??'']));
  const ledger=validAddress(v.saleLedger),collection=validAddress(v.saleCollection);
  return `<section class="ld-panel ld-sale-setup" aria-label="Community launch infrastructure"><div class="ld-panel-heading"><div><span class="ld-eyebrow">COMMUNITY CAPITAL / SETUP</span><h3>Give your community a beginning.</h3></div></div><p>Use your existing ANIMA launchpad, or deploy its community funding contracts here. Each deployment has an exact transaction review and its own wallet confirmation.</p>${!account?`<p>Connect your wallet to verify or deploy the contracts on your chosen chain.</p>${button('connect','Connect wallet',true)}`:''}
    <div class="ld-two"><section><h4>Open an existing launchpad</h4>${field('saleLaunchpad','Community launchpad address',v.saleLaunchpad,'The launchpad, sealed ledger, market and vesting vault are checked together.')}${account?button('sale-load','Verify & open this launchpad',true,'saleLaunchpad'):''}</section><section><h4>Deploy your community infrastructure</h4><p>The sequence is collection → ledger → market, vesting vault and launchpad → final installation.</p><p class="ld-note">New community contracts use your existing ANIMA collection. Token creation happens when you create a sale.</p></section></div>
    <details ${!validAddress(v.saleLaunchpad)?'open':''}><summary>Create or complete a deployment</summary><section class="ld-panel"><h4>1 · Connect your collection and ledger</h4><div class="ld-two">${field('saleCollection','Existing ANIMA collection',v.saleCollection,'The collection this community belongs to.')}${field('saleLedger','Community ledger',v.saleLedger,'A newly confirmed ledger address is used by the next three contracts.')}</div>${account?button('sale-setup:ledger','Review ledger deployment',false,'saleCollection'):''}${!collection?'<p>Enter the ANIMA collection address to prepare its community ledger.</p>':''}</section>
    <section class="ld-panel"><h4>2 · Create the community contracts</h4><p>Deploy each contract against the same unsealed ledger.</p>${[['saleMarket','Market','market','Creates the permanent native-currency/token market at successful settlement.'],['saleVault','Vesting vault','vault','Holds the committed founder and treasury allocations.']].map(([key,label,kind,help])=>`<div class="ld-setup-row"><div>${field(key,label,v[key],help)}</div>${account?button('sale-setup:'+kind,'Review '+label.toLowerCase()+' deployment',false,'saleLedger'):''}</div>`).join('')}<div class="ld-setup-row"><div><b>Launchpad</b><p>${esc(v.saleLaunchpad||'The confirmed address will appear in the launchpad field above.')}</p><small>Creates tokens, receives contributions and settles allocations.</small></div>${account?button('sale-setup:launchpad','Review launchpad deployment',false,'saleLedger'):''}</div>${!ledger?'<p>Deploy or enter the ledger in step 1 to prepare these contracts.</p>':''}</section>
    <section class="ld-panel"><h4>3 · Install the contracts together</h4><p>Final installation permanently binds the market, vault and launchpad to this ledger. All three are verified before preparing the transaction.</p>${account?button('sale-setup:seal','Review final installation',true,'saleLedger saleMarket saleVault saleLaunchpad'):''}<p>Fill in the four confirmed contract addresses to prepare final installation.</p><p class="ld-note">After confirmation, open the verified launchpad to create a sale or participate.</p></section></details></section>`;
}
